class SyncJob
{
    // Breaking change #5: EF 9 Cosmos provider requires async API.
    // Synchronous calls like ToList()/SaveChanges() now throw by default.
    // Fix: use async equivalents.
    async Task RunAsync(BlogContext context)
    {
        var blogs = await context.Blogs.ToListAsync();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        await context.SaveChangesAsync();
    }

    // Breaking change #6: Raw SQL queries must update property names.
    // Old: SELECT * FROM c WHERE c.Discriminator = 'Blog'
    // Fix: Still works IF you configured HasDiscriminator("Discriminator") above.
    // If you did NOT configure it, you'd need:
    //   SELECT * FROM c WHERE c["$type"] = 'Blog'
}

